/* CONFIG - central error handling + STOP/HELP suppression. */
const CONFIG = {
  SUPPRESSION_URL: $env.SUPPRESSION_URL || "YOUR_SUPPRESSION_STORE_URL",
  SUPPRESSION_KEY: $env.SUPPRESSION_KEY || "YOUR_SERVICE_KEY",
  HELP_TEXT: "This number belongs to YOUR BUSINESS NAME. For help call YOUR_PHONE or email YOUR_EMAIL. Reply STOP to opt out."
};
const H = this.helpers;
const HDRS = { apikey: CONFIG.SUPPRESSION_KEY, Authorization: "Bearer " + CONFIG.SUPPRESSION_KEY, "Content-Type": "application/json" };
const j = $input.first().json;
const b = j.body || j;

// Branch A: inbound SMS keyword (STOP/HELP and equivalents)
const inboundText = String(b.Body || b.text || "").trim().toUpperCase();
const fromNum = String(b.From || b.phone || "").trim();
if (inboundText && fromNum) {
  const stopWords = ["STOP","STOPALL","UNSUBSCRIBE","CANCEL","END","QUIT"];
  if (stopWords.includes(inboundText)) {
    // process suppression IMMEDIATELY and durably; failure here is an incident
    try {
      await H.httpRequest({ method: "POST", url: CONFIG.SUPPRESSION_URL + "/rest/v1/suppressions",
        headers: HDRS, body: { phone: fromNum, channel: "sms", keyword: inboundText, created_at: new Date().toISOString() }, json: true });
      return [{ json: { handled: "opt_out", phone: fromNum, ack: "You are opted out and will receive no more messages. Reply HELP for help." } }];
    } catch (e) {
      return [{ json: { handled: "INCIDENT_suppression_failed", severity: "SEV-2", phone: fromNum,
        alert: "Suppression write FAILED for " + fromNum + ": " + String(e.message||e).slice(0,140) + ". Halt outbound messaging for this contact manually NOW." } }];
    }
  }
  if (inboundText === "HELP" || inboundText === "INFO") {
    return [{ json: { handled: "help", phone: fromNum, ack: CONFIG.HELP_TEXT } }];
  }
  return [{ json: { handled: "pass_through", phone: fromNum } }];
}

// Branch B: workflow error event (wire this workflow as the n8n Error Workflow,
// or POST {error:{...}} to it). Classify, redact, alert.
const err = b.error || j.execution || {};
const msg = String(err.message || err.description || "unknown").slice(0, 300)
  .replace(/(sk-[A-Za-z0-9_\-]{8,}|Bearer\s+[A-Za-z0-9._\-]{10,}|eyJ[A-Za-z0-9._\-]{10,})/g, "[REDACTED]");
const workflowName = String((j.workflow && j.workflow.name) || err.workflow || "unknown");
const retriable = /timeout|429|rate|ECONNRESET|ETIMEDOUT|503|502/i.test(msg);
const severity = /auth|401|403|credential|suppress/i.test(msg) ? "SEV-2" : (retriable ? "SEV-3" : "SEV-3");
return [{ json: { handled: "error_event", severity, retriable, workflow: workflowName,
  alert: "[" + severity + "] " + workflowName + " failed: " + msg + (retriable ? " (retriable)" : " (needs manual review)") } }];
